        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}`;

const candidates = [
  "structurizr.inspection.missingDocs",
  "structurizr.inspection.missingAdrs",
  "structurizr.inspection.softwareSystemMissingDocumentation",
  "structurizr.inspection.softwareSystemMissingDocs",
  "structurizr.inspection.softwareSystemMissingDecisions",
  "structurizr.inspection.softwareSystemMissingAdrs",
  "structurizr.inspection.systemMissingDocumentation",
  "structurizr.inspection.systemMissingDocs",
  "structurizr.inspection.systemMissingDecisions",
  "structurizr.inspection.systemMissingAdrs",
  "structurizr.inspection.missingSystemDocumentation",
  "structurizr.inspection.missingSystemDecisions"
];

const results = {};
for (const candidate of candidates) {
  const props = `        properties {\n            "${candidate}" "ignore"\n        }\n\n`;
  const dsl = baseDsl(props);
  let inspect;
  try {
    inspect = await tools.structurizr.inspect({ dsl });
  } catch (e) {
    inspect = "EXCEPTION: " + e.message;
  }
  results[candidate] = inspect;
}

return results;
"}

